// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import "./AacProductionCustodyGateBridge.sol";

/// @notice Cover API used by the Base-origin settle path (obstacle 1 + 2).
interface IAacCheckpointMessageCover {
    struct Header {
        uint256 slot;
        uint256 proposer;
        bytes32 parentRoot;
        bytes32 stateRoot;
        bytes32 bodyRoot;
    }

    struct Aggregate {
        bytes signerUncompressed;
        bytes bits;
        Header attested;
        uint256 signatureSlot;
        bytes signaturePoint;
    }

    function cover(
        Aggregate calldata input,
        Header calldata finalized,
        bytes32[7] calldata finalityBranch,
        bytes calldata baseHeaderRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        uint64 receiptIndex,
        uint256 logIndex,
        Header[] calldata beaconHeaders
    ) external returns (bytes32 operationId, uint256 amount, bool messageCovered_, bool headerFinal_);
}

/// @notice CoNET-origin inclusion cover (F2): Aggregate + CoNET EL + receipt MPT.
interface IAacConetMessageInclusion {
    struct Header {
        uint256 slot;
        uint256 proposer;
        bytes32 parentRoot;
        bytes32 stateRoot;
        bytes32 bodyRoot;
    }

    struct Aggregate {
        bytes signerUncompressed;
        bytes bits;
        Header attested;
        uint256 signatureSlot;
        bytes signaturePoint;
    }

    function cover(
        Aggregate calldata input,
        bytes calldata conetHeaderRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        uint64 receiptIndex,
        uint256 logIndex,
        Header[] calldata beaconHeaders
    ) external returns (bytes32 operationId, uint256 amount, bool messageCovered_, bool aggregateOk_);
}

/// @notice Obstacle 5 settler for the production custody proxy.
/// @dev Storage layout matches Beacon/Bridge (initialized, owner, proofLink, __gap).
///      Does not consume AAC, does not open custody, does not grant Treasury/GB/Peer.
contract AacProductionCustodyGateSettler is AacProductionCustodyGateBridge {
    address public constant COVER = 0x01506527a4Dab14141038Db15f5341dcF4729233;
    /// @dev Patched by executeF2ConetInclusion.mjs after AacConetMessageInclusion deploy.
    address public constant CONET_INCLUSION = 0x7064860E3594aE120f71700B2F46151c6D370559;

    uint8 private constant ORIGIN_BASE = 1;
    uint8 private constant ORIGIN_CONET = 2;

    error GateFailed();

    event Settled(bytes32 indexed operationId, uint256 amount, uint8 origin);

    /// @notice Base-origin settle: same call must pass COVER.cover (obstacles 1+2).
    function settle(
        IAacCheckpointMessageCover.Aggregate calldata input,
        IAacCheckpointMessageCover.Header calldata finalized,
        bytes32[7] calldata finalityBranch,
        bytes calldata baseHeaderRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        uint64 receiptIndex,
        uint256 logIndex,
        IAacCheckpointMessageCover.Header[] calldata beaconHeaders
    ) external returns (bytes32 operationId, uint256 amount) {
        return _settleCover(
            input,
            finalized,
            finalityBranch,
            baseHeaderRlp,
            receiptRlp,
            proofNodes,
            receiptIndex,
            logIndex,
            beaconHeaders
        );
    }

    /// @notice Base-origin settleBridge: same COVER gate as settle (not quote-only).
    function settleBridge(
        IAacCheckpointMessageCover.Aggregate calldata input,
        IAacCheckpointMessageCover.Header calldata finalized,
        bytes32[7] calldata finalityBranch,
        bytes calldata baseHeaderRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        uint64 receiptIndex,
        uint256 logIndex,
        IAacCheckpointMessageCover.Header[] calldata beaconHeaders
    ) external returns (bytes32 operationId, uint256 amount) {
        return _settleCover(
            input,
            finalized,
            finalityBranch,
            baseHeaderRlp,
            receiptRlp,
            proofNodes,
            receiptIndex,
            logIndex,
            beaconHeaders
        );
    }

    /// @notice CoNET-origin settle: independent Aggregate + EL receipt inclusion (F2).
    /// @dev Rejects the pre-F2 self-hash gate (settleFromConet(bytes32,uint256,bytes)).
    function settleFromConet(
        IAacConetMessageInclusion.Aggregate calldata input,
        bytes calldata conetHeaderRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        uint64 receiptIndex,
        uint256 logIndex,
        IAacConetMessageInclusion.Header[] calldata beaconHeaders
    ) external returns (bytes32 operationId, uint256 amount) {
        if (CONET_INCLUSION == address(0)) revert GateFailed();
        bool covered;
        bool aggregateOk_;
        (operationId, amount, covered, aggregateOk_) = IAacConetMessageInclusion(CONET_INCLUSION).cover(
            input,
            conetHeaderRlp,
            receiptRlp,
            proofNodes,
            receiptIndex,
            logIndex,
            beaconHeaders
        );
        if (!covered || !aggregateOk_ || operationId == bytes32(0) || amount == 0) revert GateFailed();
        emit Settled(operationId, amount, ORIGIN_CONET);
    }

    function _settleCover(
        IAacCheckpointMessageCover.Aggregate calldata input,
        IAacCheckpointMessageCover.Header calldata finalized,
        bytes32[7] calldata finalityBranch,
        bytes calldata baseHeaderRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        uint64 receiptIndex,
        uint256 logIndex,
        IAacCheckpointMessageCover.Header[] calldata beaconHeaders
    ) private returns (bytes32 operationId, uint256 amount) {
        bool covered;
        bool headerFinal_;
        (operationId, amount, covered, headerFinal_) = IAacCheckpointMessageCover(COVER).cover(
            input,
            finalized,
            finalityBranch,
            baseHeaderRlp,
            receiptRlp,
            proofNodes,
            receiptIndex,
            logIndex,
            beaconHeaders
        );
        if (!covered || !headerFinal_ || operationId == bytes32(0) || amount == 0) revert GateFailed();
        emit Settled(operationId, amount, ORIGIN_BASE);
    }
}

contracts/AacProductionCustodyGateBridge.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

import "./AacProductionCustodyGateBeacon.sol";

struct AacBridgeHeader {
    uint64 slot;
    uint64 proposerIndex;
    bytes32 parentRoot;
    bytes32 stateRoot;
    bytes32 bodyRoot;
}

interface IAacBaseBridgeBeaconCheckpointExtension {
    function verify(
        bytes calldata headerRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        AacBridgeHeader[] calldata bridgeHeaders,
        AacBridgeHeader[] calldata extensionHeaders
    )
        external
        view
        returns (
            bytes32 baseBlockHash,
            bytes32 operationId,
            bytes32 bridgeBeaconRoot,
            bytes32 checkpointRoot,
            uint256 links,
            bool headerFinal
        );
}

/// @notice Closed production gate that can quote the 0.01 USDC bridge proof.
/// @dev Storage layout matches the previous implementation. `settle` and
/// `settleBridge` revert. This upgrade does not open custody.
contract AacProductionCustodyGateBridge is AacProductionCustodyGateBeacon {
    address public constant BRIDGE_EXTENSION = 0x1ffD76a3176AD6e91b123e567D9A7EeF5bC5AE2b;
    bytes32 public constant BRIDGE_BLOCK_HASH =
        0xa3e839c0470a159f18b0efc873fbe56df0e5415a46a560c9b570fb387c7b7d08;
    bytes32 public constant BRIDGE_OPERATION_ID =
        0xbd91f602e72f2e2facb4e1de3291577179d60f45cc65e386819fa219a4bd1654;
    bytes32 public constant BRIDGE_BEACON_ROOT =
        0x0fd49e9e9fcf2db840cbcd14744c84ada07605f71334d8eec6f5cc72684109d5;
    bytes32 public constant BRIDGE_CHECKPOINT_ROOT =
        0x480505bce46a8902cd88c95f6a2a3d9998c8cbdffd25f9c4aa7ef81d3a5e6453;
    uint256 public constant BRIDGE_LINKS = 580;

    function quoteBridge(
        bytes calldata headerRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        AacBridgeHeader[] calldata bridgeHeaders,
        AacBridgeHeader[] calldata extensionHeaders
    )
        external
        view
        returns (
            bytes32 baseBlockHash,
            bytes32 operationId,
            bytes32 bridgeBeaconRoot,
            bytes32 checkpointRoot,
            uint256 links,
            bool headerFinal_
        )
    {
        bool reportedFinal;
        (baseBlockHash, operationId, bridgeBeaconRoot, checkpointRoot, links, reportedFinal) =
            IAacBaseBridgeBeaconCheckpointExtension(BRIDGE_EXTENSION).verify(
                headerRlp, receiptRlp, proofNodes, bridgeHeaders, extensionHeaders
            );
        if (reportedFinal) revert UnexpectedFinality();
        if (
            baseBlockHash != BRIDGE_BLOCK_HASH || operationId != BRIDGE_OPERATION_ID
                || bridgeBeaconRoot != BRIDGE_BEACON_ROOT || checkpointRoot != BRIDGE_CHECKPOINT_ROOT
                || links != BRIDGE_LINKS
        ) revert InvalidQuote();
        headerFinal_ = false;
    }

    function settleBridge(
        bytes calldata headerRlp,
        bytes calldata receiptRlp,
        bytes[] calldata proofNodes,
        AacBridgeHeader[] calldata bridgeHeaders,
        AacBridgeHeader[] calldata extensionHeaders
    ) external view {
        this.quoteBridge(headerRlp, receiptRlp, proofNodes, bridgeHeaders, extensionHeaders);
        revert CustodyClosed();
    }
}

contracts/AacProductionCustodyGateBeacon.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.35;

interface IAacBaseAnchorHeaderLogLink {
    function verify(
        bytes[] calldata headers,
        bytes calldata ethereumHeaderRlp,
        bytes[] calldata gameAccountProof,
        bytes calldata gameCode,
        bytes calldata baseHeaderRlp,
        bytes[] calldata messagePasserProof,
        uint64 receiptIndex,
        bytes calldata receiptValue,
        bytes[] calldata receiptProof,
        uint256 logIndex
    )
        external
        view
        returns (
            bytes32 newestHash,
            bytes32 outputRoot,
            address from,
            address to,
            uint256 amount,
            uint256 links,
            bool headerFinal
        );
}

interface IAacBaseAnchorBeaconRootLink {
    struct LogInputs {
        bytes[] headers;
        bytes ethereumHeaderRlp;
        bytes[] gameAccountProof;
        bytes gameCode;
        bytes baseHeaderRlp;
        bytes[] messagePasserProof;
        uint64 receiptIndex;
        bytes receiptValue;
        bytes[] receiptProof;
        uint256 logIndex;
    }

    struct BeaconInputs {
        bytes[] accountProof;
        bytes[] timestampProof;
        bytes[] rootProof;
    }

    function verify(LogInputs calldata logInputs, BeaconInputs calldata beaconInputs)
        external
        view
        returns (
            bytes32 newestHash,
            bytes32 outputRoot,
            bytes32 parentBeaconBlockRoot,
            address from,
            uint256 amount,
            uint256 links,
            bool headerFinal
        );
}

/// @notice Second implementation of the closed production custody gate.
/// @dev Storage layout matches the first implementation. `quoteBeacon` reads
/// the accepted beacon-root link. This implementation still cannot settle,
/// and `headerFinal` stays false.
contract AacProductionCustodyGateBeacon {
    bytes32 private constant IMPLEMENTATION_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    address public constant BEACON_LINK = 0x11b7f8cD851dD3f990686f86ABD2179E9bF413e2;
    bytes32 public constant NEWEST_HASH =
        0xbeeaebea63023a336d15c612675ccc8de94b5b86700d4809ceda897d4638d725;

    address private immutable self = address(this);

    uint8 private initialized;
    address public owner;
    address public proofLink;
    uint256[47] private __gap;

    error AlreadyInitialized();
    error NotProxy();
    error NotOwner();
    error BadAddress();
    error CustodyClosed();
    error UnexpectedFinality();
    error InvalidQuote();

    constructor() {
        initialized = 1;
    }

    function initialize(address owner_, address proofLink_) external {
        if (initialized != 0) revert AlreadyInitialized();
        if (owner_ == address(0) || proofLink_ == address(0)) revert BadAddress();
        initialized = 1;
        owner = owner_;
        proofLink = proofLink_;
    }

    function headerFinal() external pure returns (bool) {
        return false;
    }

    function custodyOpen() external pure returns (bool) {
        return false;
    }

    function settle() external pure {
        revert CustodyClosed();
    }

    function quote(
        bytes[] calldata headers,
        bytes calldata ethereumHeaderRlp,
        bytes[] calldata gameAccountProof,
        bytes calldata gameCode,
        bytes calldata baseHeaderRlp,
        bytes[] calldata messagePasserProof,
        uint64 receiptIndex,
        bytes calldata receiptValue,
        bytes[] calldata receiptProof,
        uint256 logIndex
    )
        external
        view
        returns (
            bytes32 newestHash,
            bytes32 outputRoot,
            address from,
            address to,
            uint256 amount,
            uint256 links,
            bool headerFinal_
        )
    {
        bool reportedFinal;
        (newestHash, outputRoot, from, to, amount, links, reportedFinal) =
            IAacBaseAnchorHeaderLogLink(proofLink).verify(
                headers,
                ethereumHeaderRlp,
                gameAccountProof,
                gameCode,
                baseHeaderRlp,
                messagePasserProof,
                receiptIndex,
                receiptValue,
                receiptProof,
                logIndex
            );
        if (reportedFinal) revert UnexpectedFinality();
        headerFinal_ = false;
    }

    function quoteBeacon(
        IAacBaseAnchorBeaconRootLink.LogInputs calldata logInputs,
        IAacBaseAnchorBeaconRootLink.BeaconInputs calldata beaconInputs
    )
        external
        view
        returns (
            bytes32 newestHash,
            bytes32 outputRoot,
            bytes32 parentBeaconBlockRoot,
            address from,
            uint256 amount,
            uint256 links,
            bool headerFinal_
        )
    {
        bool reportedFinal;
        (newestHash, outputRoot, parentBeaconBlockRoot, from, amount, links, reportedFinal) =
            IAacBaseAnchorBeaconRootLink(BEACON_LINK).verify(logInputs, beaconInputs);
        if (reportedFinal) revert UnexpectedFinality();
        if (newestHash != NEWEST_HASH || parentBeaconBlockRoot == bytes32(0) || links != 100) revert InvalidQuote();
        headerFinal_ = false;
    }

    function upgradeTo(address newImplementation) external {
        if (msg.sender != owner) revert NotOwner();
        if (address(this) == self || _implementation() != self) revert NotProxy();
        if (newImplementation == address(0) || newImplementation.code.length == 0) revert BadAddress();
        assembly {
            sstore(0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc, newImplementation)
        }
    }

    function _implementation() private view returns (address impl) {
        bytes32 slot = IMPLEMENTATION_SLOT;
        assembly {
            impl := sload(slot)
        }
    }
}
